fn wire_job_source(source:kernel::OriginalJobSource)->semio_framework_plugin_abi::wasip2::JobSource{semio_framework_plugin_abi::wasip2::JobSource{job:source.job,kind:source.kind,input:source.input,checkpoint:source.checkpoint}}
/// 📥️ The actual job export retains its pending whole admission under the shared admitted actor entry.
