fn original_job_binding(job:u64,input:RetainedTurnInput)->Result<(),ValueRefusalKind>{let identity=semio_framework_plugin_reactor_jobs::original_job_identity(job).or_else(||with_entry(|entry|entry.original_job_output_identity().filter(|identity|identity.0==job).map(|identity|(identity.1,identity.2))).ok().flatten());match identity{None=>Err(ValueRefusalKind::InvalidValue),Some(identity)if identity!=(input.operation,input.generation)=>Err(ValueRefusalKind::OwnershipLimit),Some(_)=>Ok(())}}
